-- ============================================================================
-- The Tradeyard -- chrome_black card_catalog import
--
-- Adds the 7th set, 2025 Topps Chrome Black Football, to public.card_catalog:
-- 475 rows from chrome_black_cards_checklist_import.csv, same shape as the
-- existing 6-set import in card_catalog_import/ (card_catalog.sql must already
-- be applied). Like that checklist data, print_run and source_page are empty
-- for every row here too -- this source never carried them; print runs for
-- this set live in parallels (see chrome_black_parallels_seed.sql) same as the
-- other 6 sets.
--
-- Unlike the original 21-part import (a one-time bulk load into an empty
-- table), this deletes any existing rows for this one set_name first, so it
-- is safe to run more than once without creating duplicates.
-- ============================================================================

delete from public.card_catalog where set_name = '2025 Topps Chrome Black Football';

